<?php
declare(strict_types=1);
function qa180_customers(App $app,array $user,array $tenant,string $section):void {
    if(is_post()){verify_csrf();try{
        $cid=(int)($_POST['customer_id']??0);$action=(string)($_POST['action']??'');
        if($action==='credit'){
            qa180_permission($app,$user,'credito','credit');$limit=r2_number($_POST['credit_limit']??0);$days=(int)r2_number($_POST['payment_terms_days']??30,1,3650);$notes=mb_substr(trim((string)($_POST['notes']??'')),0,1000);
            $app->db->beginTransaction();$linked=$app->one('SELECT user_id FROM tenant_customers WHERE tenant_id=? AND user_id=? FOR UPDATE',[$tenant['id'],$cid]);if(!$linked)throw new DomainException('Este cliente no pertenece al negocio.');
            $app->one('SELECT id FROM customer_credit_profiles WHERE tenant_id=? AND user_id=? FOR UPDATE',[$tenant['id'],$cid]);
            $app->exec('INSERT INTO customer_credit_profiles(tenant_id,user_id,credit_enabled,credit_limit,payment_terms_days,is_blocked,notes) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE credit_enabled=VALUES(credit_enabled),credit_limit=VALUES(credit_limit),payment_terms_days=VALUES(payment_terms_days),is_blocked=VALUES(is_blocked),notes=VALUES(notes)',[$tenant['id'],$cid,isset($_POST['credit_enabled'])?1:0,$limit,$days,isset($_POST['is_blocked'])?1:0,$notes]);
            qa180_audit($app,$user,'customer_credit','customer',$cid,'Actualizó crédito del cliente: límite '.money($limit).', plazo '.$days.' días'.(isset($_POST['is_blocked'])?', bloqueado':''));$app->db->commit();
        }elseif($action==='create'){
            qa180_permission($app,$user,'clientes','write');$app->db->beginTransaction();$app->one('SELECT id FROM tenants WHERE id=? FOR UPDATE',[$tenant['id']]);$new=r2_new_customer($app,$tenant,(string)($_POST['name']??''),(string)($_POST['phone']??''),$user,'panel');$cid=(int)$new['id'];qa180_audit($app,$user,'customer_create','customer',$cid,'Registró al cliente '.$new['name']);$app->db->commit();
        }else throw new DomainException('Acción no disponible.');flash('success','Cliente guardado.');
    }catch(Throwable $error){if($app->db->inTransaction())$app->db->rollBack();flash('error',$error instanceof PDOException?'No se guardaron los cambios del cliente.':$error->getMessage());}redirect(url('admin/'.$section.($cid?'?customer='.$cid.'&tab='.($action==='credit'?'credito':'general'):'')));}
    $q=mb_substr(trim((string)($_GET['q']??'')),0,100);$cid=(int)($_GET['customer']??0);$tab=(string)($_GET['tab']??'general');
    $title=['clientes-crear'=>'Crear cliente','clientes-buscar'=>'Buscar clientes','clientes-historial'=>'Historial de clientes','credito'=>'Crédito'][$section]??'Clientes';
    admin_shell_start($title,$user,$tenant,$section);
    if($section==='clientes-crear'&&!$cid){echo '<section class="card admin-card">'.r2_form('create').field('Nombre','name','',true).field('Teléfono de Costa Rica','phone','',true).'<button class="btn">Guardar cliente</button></form></section>';admin_shell_end();return;}
    $detail=$cid?$app->one('SELECT u.id,u.name,u.phone,u.email,u.created_at,cp.credit_enabled,cp.credit_limit,cp.current_balance,cp.payment_terms_days,cp.is_blocked,cp.notes FROM tenant_customers tc JOIN users u ON u.id=tc.user_id LEFT JOIN customer_credit_profiles cp ON cp.tenant_id=tc.tenant_id AND cp.user_id=u.id WHERE tc.tenant_id=? AND tc.user_id=?',[$tenant['id'],$cid]):null;
    if($detail){
        echo '<section class="card admin-card"><h2>'.e($detail['name']).'</h2><nav class="qa180-tabs">';foreach(['general'=>'General','credito'=>'Crédito','estado'=>'Estado de cuenta','ventas'=>'Ventas','fidelizacion'=>'Fidelización'] as $key=>$label)echo '<a class="btn '.($tab===$key?'':'btn-light').'" href="'.e(url('admin/'.$section.'?customer='.$cid.'&tab='.$key)).'">'.$label.'</a>';echo '</nav>';
        if($tab==='credito'){
            echo '<p>Saldo pendiente '.money((float)$detail['current_balance']).' · Disponible '.money($detail['credit_enabled']&&!$detail['is_blocked']?max(0,(float)$detail['credit_limit']-(float)$detail['current_balance']):0).'</p>';
            $may=restructure_can_r1($app,$user,'credito','credit');if($may===true||($may===null&&in_array($user['role'],['tenant_admin','manager'],true)))echo r2_form('credit').pos_hidden_148('customer_id',$cid).'<label><input type="checkbox" name="credit_enabled" '.($detail['credit_enabled']?'checked':'').'> Crédito autorizado</label><label><input type="checkbox" name="is_blocked" '.($detail['is_blocked']?'checked':'').'> Bloquear nuevas ventas a crédito (conserva las deudas)</label>'.field('Límite','credit_limit',$detail['credit_limit']??0,true,'number','.01').field('Plazo en días','payment_terms_days',$detail['payment_terms_days']??30,true,'number','1').field('Notas','notes',$detail['notes']??'').'<button class="btn">Guardar crédito</button></form>';
            else echo '<p>Tu rol permite consultar el crédito. El dueño o un rol autorizado puede modificarlo.</p>';
        }elseif($tab==='estado'){
            echo '<div class="table-wrap"><table class="table"><tr><th>Documento</th><th>Vence</th><th>Monto original</th><th>Saldo</th><th></th></tr>';foreach($app->all('SELECT id,document_number,due_date,amount,balance FROM accounts_receivable WHERE tenant_id=? AND customer_id=? ORDER BY id DESC LIMIT 200',[$tenant['id'],$cid]) as $row)echo '<tr><td>'.e($row['document_number']).'</td><td>'.e($row['due_date']).'</td><td>'.money((float)$row['amount']).'</td><td>'.money((float)$row['balance']).'</td><td><a class="btn btn-light" href="'.e(url('admin/cxc?detail='.$row['id'])).'">Ver abonos / abonar</a></td></tr>';echo '</table></div>';
        }elseif($tab==='ventas'){
            echo '<div class="table-wrap"><table class="table"><tr><th>Fecha</th><th>Documento</th><th>Canal</th><th>Total</th><th>Estado</th></tr>';foreach($app->all('SELECT created_at,order_number number,"Web" channel,total,status FROM orders WHERE tenant_id=? AND user_id=? UNION ALL SELECT created_at,sale_number,"Caja",total,status FROM sales WHERE tenant_id=? AND customer_id=? ORDER BY created_at DESC LIMIT 200',[$tenant['id'],$cid,$tenant['id'],$cid]) as $row)echo '<tr><td>'.e($row['created_at']).'</td><td>'.e($row['number']).'</td><td>'.e($row['channel']).'</td><td>'.money((float)$row['total']).'</td><td>'.e(ui_label_qa($row['status'])).'</td></tr>';echo '</table></div>';
        }elseif($tab==='fidelizacion'){
            $account=$app->one('SELECT * FROM loyalty_accounts WHERE tenant_id=? AND user_id=?',[$tenant['id'],$cid]);echo '<h3>Premia las compras de tus clientes</h3><p>Ejemplo: ganar 1 punto por cada ₡1.000 comprados. Con 10 puntos puedes ofrecer una recompensa configurada en Fidelización. Los puntos se registran al completar la venta; no por abrir una cuenta.</p>';if($account)echo '<p>Cuenta de fidelización activa. Revisa los movimientos y recompensas desde Fidelización.</p>';else echo '<p>Este cliente todavía no tiene movimientos de fidelización. Aparecerán cuando complete una compra elegible.</p>';echo '<a class="btn btn-light" href="'.e(url('admin/fidelizacion')).'">Configurar fidelización</a>';
        }else echo '<p>Teléfono: '.e($detail['phone']).'</p><p>Registro: '.e($detail['created_at']).'</p><p>'.($detail['credit_enabled']?'Crédito autorizado':'Sin crédito autorizado').($detail['is_blocked']?' · Nuevos créditos bloqueados':'').'</p>';
        echo '</section>';admin_shell_end();return;
    }
    echo '<section class="card admin-card"><form class="qa180-filter" method="get">'.field('Nombre o teléfono','q',$q).'<button class="btn">Buscar</button><a class="btn btn-light" href="'.e(url('admin/clientes-crear')).'">Crear cliente</a></form><div class="table-wrap"><table class="table"><tr><th>Cliente</th><th>Compras completadas</th><th>Crédito</th><th>Saldo</th><th></th></tr>';
    // Aggregate once for the business, instead of four correlated subqueries
    // per client. A received web order is listed as an order, not another sale.
    $rows=$app->all('SELECT u.id,u.name,u.phone,COALESCE(c.credit_enabled,0) credit_enabled,COALESCE(c.is_blocked,0) is_blocked,COALESCE(c.current_balance,0) current_balance,COALESCE(s.total,0) sales_total,COALESCE(s.count,0) sales_count FROM tenant_customers tc JOIN users u ON u.id=tc.user_id LEFT JOIN customer_credit_profiles c ON c.tenant_id=tc.tenant_id AND c.user_id=u.id LEFT JOIN (SELECT customer_id,COUNT(*) count,SUM(total) total FROM sales WHERE tenant_id=? AND status="completed" GROUP BY customer_id) s ON s.customer_id=u.id WHERE tc.tenant_id=? AND (u.name LIKE ? OR u.phone LIKE ?) '.($section==='credito'?'AND (c.credit_enabled=1 OR c.current_balance>0) ':'').'ORDER BY u.name,u.id LIMIT 300',[$tenant['id'],$tenant['id'],'%'.$q.'%','%'.$q.'%']);
    foreach($rows as $row)echo '<tr><td>'.e($row['name']).'<br>'.e($row['phone']).'</td><td>'.(int)$row['sales_count'].' · '.money((float)$row['sales_total']).'</td><td>'.($row['is_blocked']?'Bloqueado':($row['credit_enabled']?'Autorizado':'Sin crédito')).'</td><td>'.money((float)$row['current_balance']).'</td><td><a class="btn btn-light" href="?customer='.(int)$row['id'].'&tab='.($section==='credito'?'credito':'general').'">Abrir ficha</a></td></tr>';if(!$rows)echo '<tr><td colspan="5">'.($section==='credito'?'No hay clientes con crédito autorizado o deuda pendiente. Abre una ficha desde Buscar clientes para autorizarlo.':'No hay clientes con esos datos. Puedes registrar el primero.').'</td></tr>';echo '</table></div></section>';admin_shell_end();
}
